# Configuration file for the Sphinx documentation builder.
#
# Copied from pyobs-core's docs/templates/gui-nonpython-conf.py (see
# specs/steering/docs-structure-by-project-group.md's gui-nonpython group) — the driver-module
# conf.py with the Python-only autodoc/napoleon/viewcode extensions dropped. The C++ API reference
# under api/ is generated by Doxygen + doxysphinx as a pre-build step, not a Sphinx extension —
# see ../Doxyfile and .readthedocs.yml.
#
# For a full list of options see: http://www.sphinx-doc.org/en/stable/config

# -- Project information -----------------------------------------------------

project = "pyobs-polaris"
copyright = "2026, Tim-Oliver Husser"
author = "Tim-Oliver Husser"


# -- General configuration ---------------------------------------------------

add_module_names = False

extensions = [
    "sphinx.ext.githubpages",
    "sphinx.ext.autosectionlabel",
    "sphinx.ext.intersphinx",
]

templates_path = ["_templates"]
source_suffix = ".rst"
master_doc = "index"
language = "en"
exclude_patterns = []
pygments_style = "sphinx"

nitpicky = True
nitpick_ignore = []

intersphinx_mapping = {
    "pyobs": ("https://pyobs-core.readthedocs.io/en/latest/", None),
}

# -- Options for HTML output -------------------------------------------------

html_theme = "sphinx_rtd_theme"
html_theme_options = {
    # No "display_version" here: sphinx_rtd_theme 3.1.0 removed support for it, and -W
    # (warnings-as-errors) turns the resulting warning into a build failure.
    "collapse_navigation": False,
    "sticky_navigation": True,
    "navigation_depth": 4,
    "logo_only": False,
    "prev_next_buttons_location": "bottom",
    "titles_only": False,
    "style_nav_header_background": "#cccccc",
}
html_logo = "_static/pyobs.gif"
